#include <bits/stdc++.h>
using namespace std;

vector<int> anti_sort(size_t n) {
    vector<int> res(2 * n + 1);
    iota(res.begin(), res.end(), 0);
    for (size_t i = n; i-- > 0;) {
        swap(res[2 * i + 1], res[i + n]);
    }
    for (auto &x : res) x++;
    return res;
}

